/*
 * Design a HashSet without using any built‑in hash table libraries.
 * The key range is 0 … 1,000,000, so a simple boolean vector is sufficient.
 class MyHashSet {
private:
    static constexpr int MAX_KEY = 1'000'000;          // inclusive upper bound
    std::vector<bool> present;                         // presence flag for each key

public:
    /** Initialize your data structure here.     MyHashSet() : present(MAX_KEY + 1, false) {}

    /** Inserts the value key into the HashSet.     void add(int key) {
        // Guard against out‑of‑range keys (defensive programming)
        if (key < 0 || key > MAX_KEY) return;
        present[key] = true;
    }

    /** Removes the value key from the HashSet.     void remove(int key) {
        if (key < 0 || key > MAX_KEY) return;
        present[key] = false;
    }

    /** Returns true if this set contains the specified element.     bool contains(int key) {
        if (key < 0 || key > MAX_KEY) return false;
        return present[key];
    }
};

